"use strict";(globalThis.webpackChunkistqb_quiz=globalThis.webpackChunkistqb_quiz||[]).push([[651],{651(e){e.exports=JSON.parse('[{"term":"Error (Equivocaci\xf3n)","definition":"Acci\xf3n humana que produce un resultado incorrecto."},{"term":"Defecto (Bug / Falta)","definition":"Imperfecci\xf3n o deficiencia en un producto de trabajo."},{"term":"Falla (Failure)","definition":"Comportamiento inesperado o incorrecto del software en ejecuci\xf3n."},{"term":"Paradoja del Pesticida","definition":"Si se repiten las mismas pruebas, eventualmente dejar\xe1n de encontrar nuevos defectos."},{"term":"Shift-left","definition":"Realizar actividades de prueba lo m\xe1s temprano posible en el ciclo de vida."},{"term":"Pruebas de Componentes","definition":"Nivel de prueba enfocado en unidades individuales de c\xf3digo aisladas."},{"term":"Pruebas de Integraci\xf3n","definition":"Nivel enfocado en las interacciones y las interfaces entre componentes o sistemas."},{"term":"Pruebas de Sistema","definition":"Evaluaci\xf3n del comportamiento y las capacidades de todo el sistema o producto."},{"term":"Pruebas de Aceptaci\xf3n","definition":"Pruebas realizadas por usuarios para determinar si el sistema satisface sus necesidades."},{"term":"Prueba de Regresi\xf3n","definition":"Asegurar que los cambios en el c\xf3digo no hayan afectado funcionalidades existentes."},{"term":"Prueba de Confirmaci\xf3n","definition":"Volver a probar para verificar que un defecto espec\xedfico fue corregido."},{"term":"Pruebas Est\xe1ticas","definition":"Evaluar un producto de trabajo (ej. c\xf3digo o requisitos) sin ejecutarlo."},{"term":"An\xe1lisis Est\xe1tico","definition":"Uso de herramientas (como linters) para encontrar defectos en el c\xf3digo sin ejecuci\xf3n."},{"term":"Revisi\xf3n Informal","definition":"Revisi\xf3n no documentada, sin proceso formal, como el pair programming."},{"term":"Walkthrough (Revisi\xf3n Guiada)","definition":"Revisi\xf3n donde el autor gu\xeda al equipo con fines de aprendizaje o consenso."},{"term":"Inspecci\xf3n","definition":"El tipo de revisi\xf3n m\xe1s formal, dirigida por un moderador capacitado."},{"term":"T\xe9cnicas de Caja Negra","definition":"T\xe9cnicas de prueba basadas en la especificaci\xf3n, ignorando la estructura interna."},{"term":"T\xe9cnicas de Caja Blanca","definition":"T\xe9cnicas de prueba basadas en el conocimiento de la estructura interna del c\xf3digo."},{"term":"Partici\xf3n de Equivalencia","definition":"Dividir entradas en clases v\xe1lidas e inv\xe1lidas donde el comportamiento se asume igual."},{"term":"Valores L\xedmite (BVA)","definition":"Probar los extremos num\xe9ricos de las particiones donde ocurren m\xe1s defectos."},{"term":"Tablas de Decisi\xf3n","definition":"\xdatiles para probar reglas de negocio complejas con m\xfaltiples condiciones booleanas."},{"term":"Transici\xf3n de Estado","definition":"T\xe9cnica para modelar y probar sistemas donde las acciones dependen de estados previos."},{"term":"Cobertura de Sentencias","definition":"Porcentaje de l\xedneas o instrucciones ejecutables que han sido probadas."},{"term":"Error Guessing","definition":"T\xe9cnica basada en la intuici\xf3n y experiencia del probador para predecir fallos."},{"term":"Plan de Pruebas","definition":"Documento que describe el alcance, enfoque, recursos y cronograma de las pruebas."},{"term":"Criterios de Salida (Exit Criteria)","definition":"Condiciones que deben cumplirse para dar por finalizada una actividad de prueba."},{"term":"Criterios de Entrada (Entry Criteria)","definition":"Condiciones que deben existir antes de que comience una actividad de prueba."},{"term":"Trazabilidad","definition":"Capacidad de vincular requisitos con sus casos de prueba correspondientes."},{"term":"Gesti\xf3n de la Configuraci\xf3n","definition":"Garantiza que se pruebe la versi\xf3n correcta del software y del entorno."},{"term":"Riesgo de Producto","definition":"Posibilidad de un defecto en el software que afecte la calidad (ej. vulnerabilidad)."},{"term":"Riesgo de Proyecto","definition":"Posibilidad de un evento que afecte el desarrollo (ej. p\xe9rdida de personal)."}]')}}]);